#!/usr/bin/env node

/**
 * Generate TypeScript types from package.json
 */

const fs = require('fs');
const path = require('path');

const packageJson = require('../package.json');

const types = `
/**
 * Auto-generated types from package.json
 * Do not edit this file directly
 */

export interface PackageInfo {
  name: string;
  version: string;
  description: string;
  author: string;
  license: string;
  homepage: string;
  repository: {
    type: string;
    url: string;
    directory: string;
  };
  bugs: {
    url: string;
    email: string;
  };
  engines: {
    node: string;
    npm: string;
    yarn: string;
  };
  dependencies: Record<string, string>;
  devDependencies: Record<string, string>;
  scripts: Record<string, string>;
}

export const PACKAGE_INFO: PackageInfo = ${JSON.stringify(packageJson, null, 2)};

export const APP_VERSION = '${packageJson.version}';
export const APP_NAME = '${packageJson.name}';
export const APP_DESCRIPTION = '${packageJson.description}';

export const DEPENDENCIES = Object.keys(packageJson.dependencies || {});
export const DEV_DEPENDENCIES = Object.keys(packageJson.devDependencies || {});

export const SCRIPTS = Object.keys(packageJson.scripts || {});
`;

fs.writeFileSync(
  path.join(__dirname, '../src/types/package.types.ts'),
  types
);

console.log('✅ Package types generated');